const folders=[['Policies','document-text-outline'],['Reports','people-outline'],['Forms','reader-outline'],['Archives','archive-outline'],['Emergency procedures','shield-checkmark-outline'],['Other','folder-outline']] as const;
export default function CreateDocumentFolder(){const{id}=useLocalSearchParams<{id:string}>(),{palette}=useAppTheme();const close=()=>router.back();const create=(name:string)=>router.replace(`/community/${id}/document-folder/${encodeURIComponent(name)}` as any);return <Modal visible transparent animationType="fade" statusBarTranslucent onRequestClose={close}><Pressable accessibilityRole="button" accessibilityLabel="Close create folder" onPress={close} style={s.backdrop}><Pressable accessibilityViewIsModal onPress={()=>{}} style={[s.sheet,{backgroundColor:palette.surface}]}><View style={s.head}><View style={[s.icon,{backgroundColor:palette.primarySoft}]}><Ionicons name="folder-open-outline" size={26} color={palette.primary}/></View><View style={s.copy}><Text style={[s.title,{color:palette.text}]}>Create a new folder</Text><Muted>Choose the category for the new document folder.</Muted></View><Pressable accessibilityLabel="Cancel creating folder" onPress={close} style={s.close}><Ionicons name="close" size={24} color={palette.text}/></Pressable></View><View style={s.options}>{folders.map(([name,icon])=><Pressable key={name} accessibilityRole="button" accessibilityLabel={`Create ${name} folder`} onPress={()=>create(name)} style={[s.option,{borderColor:palette.border}]}><Ionicons name={icon} size={22} color={palette.primary}/><Text style={[s.optionText,{color:palette.text}]}>{name}</Text><Ionicons name="add-circle-outline" size={21} color={palette.primary}/></Pressable>)}</View></Pressable></Pressable></Modal>}
const s=StyleSheet.create({backdrop:{flex:1,backgroundColor:'rgba(5,18,38,.45)',alignItems:'center',justifyContent:'center',padding:22},sheet:{width:'100%',maxWidth:520,borderRadius:22,padding:18,shadowColor:'#000',shadowOpacity:.22,shadowRadius:20,elevation:20},head:{flexDirection:'row',alignItems:'center',gap:11,marginBottom:16},icon:{width:48,height:48,borderRadius:15,alignItems:'center',justifyContent:'center'},copy:{flex:1},title:{fontSize:19,fontWeight:'900',marginBottom:3},close:{width:42,height:42,alignItems:'center',justifyContent:'center'},options:{gap:8},option:{minHeight:52,borderWidth:1,borderRadius:13,paddingHorizontal:13,flexDirection:'row',alignItems:'center',gap:10},optionText:{flex:1,fontSize:15,fontWeight:'800'}});
